import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type AvatarPart = "root" | "image" | "fallback";

export const anatomy: Anatomy<AvatarPart> = createAnatomy("avatar").parts(
  "root",
  "image",
  "fallback",
);

export const parts: Record<AvatarPart, AnatomyPart> = anatomy.build();

import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./avatar.anatomy";
import { getImageId, getRootId } from "./avatar.dom";
import type { AvatarApi, AvatarSchema } from "./avatar.types";

export function connect<T extends PropTypes>(
  service: Service<AvatarSchema>,
  normalize: NormalizeProps<T>,
): AvatarApi<T> {
  const { state, context, prop, send, scope } = service;

  const status = state.get();
  const label = prop("label");
  const showFallback =
    status === "error" ||
    !context.get("hasImage") ||
    (status === "loading" && context.get("delayElapsed"));

  return {
    status,
    loaded: status === "loaded",
    showFallback,

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        // Without `label` there is no role and no name from the core: the
        // accessible name lives in the image's alt or in adjacent text.
        //
        // With it the whole avatar is one image, and that is what makes the name
        // survive a 404 — an errored `<img>` leaves the accessibility tree with
        // its `hidden`, taking its `alt` with it, and the monogram behind it is
        // decorative. A name carried by the root depends on nothing that can
        // fail. `role="img"` also makes the subtree presentational, so the inner
        // `alt` cannot double up.
        role: label === undefined ? undefined : "img",
        "aria-label": label,
        dir: prop("dir"),
        "data-state": status,
        "data-size": prop("size"),
      }),

    getImageProps: (): T["img"] =>
      normalize.img({
        ...parts.image.attrs,
        id: getImageId(scope),
        "data-state": status,
        // `hidden`, not CSS: a broken image paints the browser's glyph even
        // under an absent stylesheet, so the core removes it itself.
        hidden: status === "error" ? true : undefined,
        // An avatar is not a document to drag off the page.
        draggable: false,
        // Never `alt` — it belongs to the consumer and flows in as element props.
        onLoad: () => send({ type: "IMAGE.LOAD" }),
        onError: () => send({ type: "IMAGE.ERROR" }),
      }),

    getFallbackProps: (): T["element"] =>
      normalize.element({
        ...parts.fallback.attrs,
        "data-state": status,
        hidden: showFallback ? undefined : true,
        // Decorative typography: the accessible name lives in the alt or in
        // adjacent text, never in a monogram.
        "aria-hidden": "true",
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "avatar";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getImageId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "image");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getImageEl(scope: Scope): HTMLImageElement | null {
  return scope.getById<HTMLImageElement>(getImageId(scope));
}

/**
 * Three states that *are* the loading status: `loading | loaded | error`. No
 * interaction, no focus, no overlay — what the machine earns its keep with is
 * everything an `onload` handler alone gets wrong: the image that was `complete`
 * before any handler attached (cache, hydration), the `src` that changes under
 * the same element, the image part that is never rendered at all, and a fallback
 * delay that must not re-flash on reload.
 *
 * `delayElapsed` is a latch. Once the fallback has been revealed it stays
 * eligible through every later reload — hiding a monogram the user has already
 * seen, only to flash it back, is the exact churn the delay exists to prevent.
 *
 * The status callback fires from explicit transition actions and never from the
 * initial state's entry, so mounting notifies nothing.
 */

import { observeAttributes, observeChildren } from "../../dom/observers";
import { nextTick, timeout } from "../../dom/raf";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getImageEl, getRootEl } from "./avatar.dom";
import type { AvatarSchema } from "./avatar.types";

export const machine: Machine<AvatarSchema> = createMachine<AvatarSchema>({
  props({ props }) {
    return {
      size: "md",
      fallbackDelay: 0,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      delayElapsed: bindable<boolean>(() => ({
        defaultValue: prop("fallbackDelay") <= 0,
        debugLabel: "avatar delayElapsed",
      })),
      // The image is presumed present until the DOM says otherwise; the first
      // PARTS.SYNC corrects it. Presuming absence would flash the fallback on
      // every mount that does render an image.
      hasImage: bindable<boolean>(() => ({
        defaultValue: true,
        debugLabel: "avatar hasImage",
      })),
    };
  },

  initialState() {
    return "loading";
  },

  effects: ["trackParts"],

  states: {
    loading: {
      effects: ["checkImageState", "waitFallbackDelay", "trackSrcChange"],
      on: {
        "IMAGE.LOAD": { target: "loaded", actions: ["notifyLoaded"] },
        "IMAGE.ERROR": { target: "error", actions: ["notifyError"] },
        // Re-enter to re-arm checkImageState/trackSrcChange against the new
        // src. `delayElapsed` is NOT reset — the latch, by decision.
        "IMAGE.SRC_CHANGE": { target: "loading", reenter: true },
        "DELAY.ELAPSED": { actions: ["revealFallback"] },
        "PARTS.SYNC": [
          { guard: "imageAppeared", target: "loading", reenter: true, actions: ["syncParts"] },
          { actions: ["syncParts"] },
        ],
      },
    },

    loaded: {
      effects: ["trackSrcChange"],
      on: {
        // A src swap that fails fires `error` on the same element.
        "IMAGE.ERROR": { target: "error", actions: ["notifyError"] },
        "IMAGE.SRC_CHANGE": { target: "loading", actions: ["notifyLoading"] },
        // IMAGE.LOAD is deliberately unhandled: a re-load while loaded (srcset
        // reflow) is a no-op.
        "PARTS.SYNC": [
          { guard: "imageAppeared", target: "loading", actions: ["syncParts", "notifyLoading"] },
          { actions: ["syncParts"] },
        ],
      },
    },

    error: {
      effects: ["trackSrcChange"],
      on: {
        // A late success: a consumer retry, or a React remount with the same
        // src already in cache.
        "IMAGE.LOAD": { target: "loaded", actions: ["notifyLoaded"] },
        "IMAGE.SRC_CHANGE": { target: "loading", actions: ["notifyLoading"] },
        "PARTS.SYNC": [
          { guard: "imageAppeared", target: "loading", actions: ["syncParts", "notifyLoading"] },
          { actions: ["syncParts"] },
        ],
      },
    },
  },

  implementations: {
    guards: {
      /**
       * Absent → present only. A removal targets nothing: `syncParts` records
       * it and `showFallback` follows from `!hasImage` without a transition.
       */
      imageAppeared({ context, scope }) {
        return !context.get("hasImage") && getImageEl(scope) !== null;
      },
    },

    actions: {
      revealFallback({ context }) {
        context.set("delayElapsed", true);
      },

      syncParts({ context, scope }) {
        context.set("hasImage", getImageEl(scope) !== null);
      },

      notifyLoading({ prop }) {
        prop("onStatusChange")?.({ status: "loading" });
      },

      notifyLoaded({ prop }) {
        prop("onStatusChange")?.({ status: "loaded" });
      },

      notifyError({ prop }) {
        prop("onStatusChange")?.({ status: "error" });
      },
    },

    effects: {
      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        return observeChildren(getRootEl(scope), () => send({ type: "PARTS.SYNC" }));
      },

      /**
       * The cache catcher: an image already `complete` before any handler
       * attached (SSR hydration, disk cache) will never fire `load` again, so
       * the state is read off the element itself.
       *
       * Read now, send through a microtask — never synchronously from the
       * installer. A synchronous send would transition out of `loading` while
       * the interpreter is still installing this state's remaining effects, and
       * the cleanups it files afterwards would belong to a state nothing is in
       * any more (the tooltip's `waitOpenDelay` documents the same rule). The
       * cancel is the cleanup, so a re-enter cannot double-send.
       */
      checkImageState({ scope, send }) {
        const img = getImageEl(scope);
        if (img === null || !img.complete) return;
        return nextTick(() => {
          if (img.naturalWidth > 0) send({ type: "IMAGE.LOAD" });
          // `complete` with an empty src is neither a load nor an error — the
          // fallback delay covers that gap.
          else if (img.currentSrc !== "" || img.src !== "") send({ type: "IMAGE.ERROR" });
        });
      },

      /**
       * The clock comes off the root element rather than off `scope.getWin()`,
       * which throws where there is no document: a machine driven with no page
       * has nothing to show, and that is a silence rather than a crash (the
       * tooltip's precedent).
       */
      waitFallbackDelay({ context, prop, scope, send }) {
        if (context.get("delayElapsed")) return;
        const win = getRootEl(scope)?.ownerDocument?.defaultView;
        if (win === null || win === undefined) return;
        return timeout(
          win,
          () => send({ type: "DELAY.ELAPSED" }),
          Math.max(0, prop("fallbackDelay")),
        );
      },

      /**
       * Covers attribute mutation on the same element (vanilla, a direct
       * consumer). NOOP while the image part is absent; re-arming goes through
       * `imageAppeared` + reenter. React's node replacement is covered
       * elsewhere: the load/error handlers travel with the prop getter and
       * re-attach to the new node on their own.
       */
      trackSrcChange({ scope, send }) {
        return observeAttributes(getImageEl(scope), ["src", "srcset"], () =>
          send({ type: "IMAGE.SRC_CHANGE" }),
        );
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction } from "../../types";

/** The machine state IS the loading status — there is no second copy to drift. */
export type AvatarStatus = "loading" | "loaded" | "error";

export type AvatarSize = "xs" | "sm" | "md" | "lg" | "xl";

export interface AvatarStatusChangeDetails {
  readonly status: AvatarStatus;
}

export interface AvatarMachineProps {
  readonly dir?: Direction | undefined;
  /** Pure presentation — `data-size` on the root, never a fork in the machine. */
  readonly size?: AvatarSize | undefined;
  /**
   * Milliseconds before the fallback shows while `loading`. 0 shows it
   * immediately (the default — the monogram is
   * visible at once); a positive delay is the anti-flash opt-in for images
   * that usually arrive fast. Once revealed it stays eligible through
   * reloads — no re-flash.
   */
  readonly fallbackDelay?: number | undefined;
  /**
   * The name the avatar answers to, whether the picture arrived or not.
   *
   * Without it the accessible name lives entirely in the image's `alt`, which
   * the consumer passes as element props — and that name **disappears on a
   * 404**: an errored image is removed from the accessibility tree with
   * `hidden`, and the monogram that replaces it is decorative typography, not a
   * name. The result is an avatar that is announced while the network is up and
   * silent when it is down, which is the wrong way round.
   *
   * With it, the root becomes a single named `role="img"` — the picture, the
   * monogram and the loading state are all one image as far as assistive
   * technology is concerned, and the name never depends on the network. The
   * inner `alt` then has nothing left to say and should be `""`.
   */
  readonly label?: string | undefined;
  readonly onStatusChange?: ((details: AvatarStatusChangeDetails) => void) | undefined;
}

export interface ResolvedAvatarMachineProps extends AvatarMachineProps {
  readonly size: AvatarSize;
  readonly fallbackDelay: number;
}

export interface AvatarSchema extends MachineSchema {
  state: AvatarStatus;
  props: ResolvedAvatarMachineProps;
  context: { delayElapsed: boolean; hasImage: boolean };
  event:
    | { type: "IMAGE.LOAD" }
    | { type: "IMAGE.ERROR" }
    | { type: "IMAGE.SRC_CHANGE" }
    | { type: "DELAY.ELAPSED" }
    | { type: "PARTS.SYNC" };
  action: "revealFallback" | "syncParts" | "notifyLoading" | "notifyLoaded" | "notifyError";
  guard: "imageAppeared";
  effect: "trackParts" | "waitFallbackDelay" | "checkImageState" | "trackSrcChange";
}

export interface AvatarApi<T extends PropTypes = PropTypes> {
  readonly status: AvatarStatus;
  readonly loaded: boolean;
  readonly showFallback: boolean;
  getRootProps(): T["element"];
  getImageProps(): T["img"];
  getFallbackProps(): T["element"];
}

export { type AvatarPart, anatomy, parts } from "./avatar.anatomy";
export { connect } from "./avatar.connect";
export { getImageId, getRootId } from "./avatar.dom";
export { machine } from "./avatar.machine";
export type {
  AvatarApi,
  AvatarMachineProps,
  AvatarSchema,
  AvatarSize,
  AvatarStatus,
  AvatarStatusChangeDetails,
  ResolvedAvatarMachineProps,
} from "./avatar.types";

/**
 * Three parts and no logic: the adapter's whole job here is to let `src` and
 * `alt` through to a real `<img>` and to keep the machine's `onLoad`/`onError`
 * on it. React replaces nodes rather than mutating them, so the handlers riding
 * on the prop getter are what re-attach themselves after a swap — the core's
 * `MutationObserver` covers the other direction, for consumers who write the
 * attribute themselves.
 */

import * as avatar from "@standarui/core/avatar";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type AvatarApi = avatar.AvatarApi<ReactPropTypes>;

const AvatarContext = createPartContext<AvatarApi>("Avatar");

export interface UseAvatarProps extends avatar.AvatarMachineProps, MachineRuntimeProps {}

/** The api behind the components — prop getters, status, nothing rendered. */
export function useAvatar(props: UseAvatarProps): AvatarApi {
  return avatar.connect(useMachine(avatar.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "size",
  "fallbackDelay",
  "label",
  "onStatusChange",
] as const;

export interface AvatarRootProps extends UseAvatarProps, PartProps<"span", UseAvatarProps> {}

export function AvatarRoot(props: AvatarRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useAvatar(machineProps);

  return (
    <AvatarContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        // A `<span>`: an avatar sits in a line of text as often as in a grid,
        // and an inline box is the one a consumer cannot add back.
        element: "span",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </AvatarContext.Provider>
  );
}

export const AvatarImage: (props: PartProps<"img">) => ReactNode = createPart(AvatarContext, {
  name: "AvatarImage",
  element: "img",
  props: (api) => api.getImageProps(),
});

export const AvatarFallback: (props: PartProps<"span">) => ReactNode = createPart(AvatarContext, {
  name: "AvatarFallback",
  element: "span",
  props: (api) => api.getFallbackProps(),
});

/**
 * `<Avatar label="…" src="…">AL</Avatar>` — three nodes, no collection, and the
 * one composed layer here whose whole argument is an attribute the consumer is
 * asked *not* to write.
 *
 * **The layer writes `alt=""` on the image, and that is the accessibility fact
 * rather than a default worth overriding.** An avatar is named once, on the root:
 * `getRootProps` turns `label` into `role="img"` plus `aria-label`, so the
 * picture, the monogram and the loading state read as a single image to assistive
 * technology. A name carried by the alt instead is a name that disappears exactly
 * when it is needed — `getImageProps` writes `hidden` on `error`, which takes the
 * whole element out of the accessibility tree and its `alt` with it, and the
 * monogram behind it is decorative typography (`getFallbackProps` writes
 * `aria-hidden="true"`). The result would be an avatar announced while the network
 * is up and silent when it is down, which is the wrong way round. `role="img"`
 * also makes the subtree presentational, so an inner name could not double up
 * anyway. There is deliberately no `alt` prop: an avatar that really is named by
 * its picture reaches the attribute through `parts.image.alt`, where the choice is
 * explicit, and so does `srcSet`, `sizes` or a `loading` hint.
 *
 * **`src` is a string and the empty string counts as absent.** `""` on an `<img>`
 * is not "no picture" to a browser — it resolves against the base URL and fetches
 * the document itself, which then fails to decode, which lands the machine in
 * `error` for a picture nobody asked for. The rule is `dialog`'s `closeLabel`
 * rule, and here the cost of getting it wrong is a real request. Absent, the image
 * part is not rendered at all rather than rendered blank: the machine watches for
 * it (`PARTS.SYNC`) and `showFallback` follows from `!hasImage` on its own.
 *
 * **The fallback is `children`, not `icon`.** It is the component's one content
 * slot — the monogram, or the consumer's own silhouette SVG, which `_avatar.scss`
 * sizes against the disc. `icon` in this library means the single leading track
 * shared with a selection checkmark, reserved once per surface, and an avatar has
 * no track: both parts occupy the same grid cell. Left out, the fallback part is
 * not placed and the disc is the empty state.
 *
 * The order is the picture then the monogram, which is the order every example of
 * the parts form already writes, and it is not layout: both parts are
 * `grid-area: 1 / 1`, and which one is visible is decided by `hidden` on the
 * fallback and `opacity` on the image, never by their position.
 *
 * `label`, `size` and `fallbackDelay` are the machine's own props, inherited and
 * forwarded untouched — never re-declared here.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { AvatarFallback, AvatarImage, AvatarRoot, type UseAvatarProps } from "./avatar";

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it — including the `alt=""` above
 * and the machine's own `draggable` and `aria-hidden`. No `Omit` of `id` here,
 * unlike the collections: each of these two parts is placed once, so a fixed id is
 * a fixed id and not the same one repeated down a list.
 */
export interface AvatarParts {
  readonly image?: PartProps<"img"> | undefined;
  readonly fallback?: PartProps<"span"> | undefined;
}

export interface AvatarComposedProps
  extends UseAvatarProps,
    Omit<PartProps<"span", UseAvatarProps>, "children"> {
  /**
   * The picture. Absent — or `""`, which counts as absent — no image part is
   * placed at all, and the monogram is what the avatar is.
   */
  readonly src?: string | undefined;
  /** The fallback: initials, or a silhouette. See above for why it is `children`. */
  readonly children?: ReactNode;
  readonly parts?: AvatarParts | undefined;
}

export function Avatar(props: AvatarComposedProps): ReactNode {
  const { src, children, parts, ...root } = props;

  return (
    <AvatarRoot {...root}>
      {src == null || src === "" ? null : <AvatarImage src={src} alt="" {...parts?.image} />}
      {children == null ? null : <AvatarFallback {...parts?.fallback}>{children}</AvatarFallback>}
    </AvatarRoot>
  );
}

export type {
  AvatarMachineProps,
  AvatarSize,
  AvatarStatus,
  AvatarStatusChangeDetails,
} from "@standarui/core/avatar";
export {
  type AvatarApi,
  AvatarFallback,
  AvatarImage,
  AvatarRoot,
  type AvatarRootProps,
  type UseAvatarProps,
  useAvatar,
} from "./avatar";
export { Avatar, type AvatarComposedProps, type AvatarParts } from "./composed";
